    "JBProjects": {
      "createFor": {
        "notice": "Create a new project for the specified owner, which mints an NFT (ERC-721) into their wallet.",
        "details": "Anyone can create a project on an owner's behalf.Requires exactly `creationFee` native tokens. The fee is forwarded after the project NFT is minted.",
        "params": {
          "owner": "The address that will be the owner of the project."
        }
      },
      "setApprovalForAll": {
        "details": "Approve or remove `operator` as an operator for the caller. Operators can call {transferFrom} or {safeTransferFrom} for any token owned by the caller. Requirements: - The `operator` cannot be the address zero. Emits an {ApprovalForAll} event."
      },
      "setCreationFee": {
        "notice": "Set the native-token fee required to create a project and the address that receives it.",
        "details": "Only this contract's owner can change the fee. A non-zero fee requires a non-zero receiver. The fee may not exceed `MAX_CREATION_FEE`.",
        "params": {
          "fee": "The required creation fee. Set to 0 to disable creation fees. Must be `<= MAX_CREATION_FEE`.",
          "receiver": "The address that receives project creation fees."
        }
      },
      "setTokenUriResolver": {
        "notice": "Set the contract that resolves project NFT metadata (the `tokenURI`). This controls what artwork and JSON metadata is returned for each project's ERC-721 token.",
        "details": "Only this contract's owner can change the resolver.",
        "params": {
          "resolver": "The address of the new resolver."
        }
      },
      "balanceOf": {
        "details": "Returns the number of tokens in ``owner``'s account."
      },
      "count": {
        "notice": "The number of projects that have been created using this contract."
      },
      "creationFee": {
        "notice": "The native-token fee required to create a project."
      },
      "creationFeeReceiver": {
        "notice": "The address that receives project creation fees."
      },
      "getApproved": {
        "details": "Returns the account approved for `tokenId` token. Requirements: - `tokenId` must exist."
      },
      "isApprovedForAll": {
        "details": "Returns if the `operator` is allowed to manage all of the assets of `owner`. See {setApprovalForAll}"
      },
      "isTrustedForwarder": {
        "details": "Indicates whether any particular address is the trusted forwarder."
      },
      "MAX_CREATION_FEE": {
        "notice": "The maximum native-token fee the owner can require to create a project."
      },
      "name": {
        "details": "Returns the token collection name."
      },
      "originalPayer": {
        "notice": "The account that paid the creation fee for the project currently being created."
      },
      "owner": {
        "details": "Returns the address of the current owner."
      },
      "ownerOf": {
        "details": "Returns the owner of the `tokenId` token. Requirements: - `tokenId` must exist."
      },
      "supportsInterface": {
        "notice": "Indicates whether this contract adheres to the specified interface.",
        "details": "See {IERC165-supportsInterface}.",
        "params": {
          "interfaceId": "The ID of the interface to check for adherence to."
        }
      },
      "symbol": {
        "details": "Returns the token collection symbol."
      },
      "tokenURI": {
        "notice": "Returns the URI where the ERC-721 standard JSON of a project is hosted.",
        "params": {
          "projectId": "The ID of the project to get a URI of."
        }
      },
      "tokenUriResolver": {
        "notice": "The contract resolving each project ID to its ERC721 URI."
      },
      "trustedForwarder": {
        "details": "Returns the address of the trusted forwarder."
      },
      "approve": {
        "details": "Gives permission to `to` to transfer `tokenId` token to another account. The approval is cleared when the token is transferred. Only a single account can be approved at a time, so approving the zero address clears previous approvals. Requirements: - The caller must own the token or be an approved operator. - `tokenId` must exist. Emits an {Approval} event."
      },
      "renounceOwnership": {
        "details": "Leaves the contract without owner. It will not be possible to call `onlyOwner` functions. Can only be called by the current owner. NOTE: Renouncing ownership will leave the contract without an owner, thereby disabling any functionality that is only available to the owner."
      },
      "safeTransferFrom": {
        "details": "Safely transfers `tokenId` token from `from` to `to`. Requirements: - `from` cannot be the zero address. - `to` cannot be the zero address. - `tokenId` token must exist and be owned by `from`. - If the caller is not `from`, it must be approved to move this token by either {approve} or {setApprovalForAll}. - If `to` refers to a smart contract, it must implement {IERC721Receiver-onERC721Received}, which is called upon   a safe transfer. Emits a {Transfer} event."
      },
      "transferFrom": {
        "details": "Transfers `tokenId` token from `from` to `to`. WARNING: Note that the caller is responsible to confirm that the recipient is capable of receiving ERC-721 or else they may be permanently lost. Usage of {safeTransferFrom} prevents loss, though the caller must understand this adds an external call which potentially creates a reentrancy vulnerability. Requirements: - `from` cannot be the zero address. - `to` cannot be the zero address. - `tokenId` token must be owned by `from`. - If the caller is not `from`, it must be approved to move this token by either {approve} or {setApprovalForAll}. Emits a {Transfer} event."
      },
      "transferOwnership": {
        "details": "Transfers ownership of the contract to a new account (`newOwner`). Can only be called by the current owner."
      }
    },
