        "_checkFitsIn": [
          {
            "name": "_checkFitsIn",
            "paramTypes": [
              "uint256",
              "uint256"
            ],
            "startLine": 2279,
            "endLine": 2281,
            "source": "function _checkFitsIn(uint256 value, uint256 max) private pure {\n        if (value > max) revert JBMultiTerminal_OverflowAlert(value, max);\n    }"
          }
        ],
