            "source": "function totalRemoteBalanceOf(\n        uint256 projectId,\n        uint256 currency,\n        uint256 decimals\n    )\n        external\n        view\n        override\n        returns (uint256 balance)\n    {\n        return _aggregateRemoteValueOf({projectId: projectId, currency: currency, decimals: decimals, surplus: false});\n    }"
