            "startLine": 438,
            "endLine": 441,
            "source": "function isPoolDeployed(uint256 projectId, address terminalToken) public view returns (bool deployed) {\n        // A nonzero position token id is the marker that the pool was deployed and seeded.\n        return tokenIdOf[projectId][terminalToken] != 0;\n    }"
