        "_getSqrtPriceX96": [
          {
            "name": "_getSqrtPriceX96",
            "paramTypes": [
              "PoolKey"
            ],
            "startLine": 466,
            "endLine": 469,
            "source": "function _getSqrtPriceX96(PoolKey memory key) internal view returns (uint160 sqrtPriceX96) {\n        // Read only Slot0's price field via StateLibrary; the tick/fee fields are unused here.\n        (sqrtPriceX96,,,) = poolManager.getSlot0(key.toId());\n    }"
          }
        ],
        "_getTerminalTokenBalance": [
          {
            "name": "_getTerminalTokenBalance",
            "paramTypes": [
              "address"
            ],
            "startLine": 474,
            "endLine": 479,
            "source": "function _getTerminalTokenBalance(address terminalToken) internal view returns (uint256 balance) {\n        // Native ETH is held as the contract's ether balance, not an ERC-20 balance.\n        if (_isNativeToken(terminalToken)) return address(this).balance;\n        // Otherwise read the ERC-20 balance held by this hook.\n        return IERC20(terminalToken).balanceOf(address(this));\n    }"
          }
        ],
