        "_terminalsOf": [
          {
            "name": "_terminalsOf",
            "paramTypes": [
              "uint256",
              "bool"
            ],
            "startLine": 1933,
            "endLine": 1953,
            "source": "function _terminalsOf(\n        uint256 projectId,\n        bool shouldIgnoreFailure\n    )\n        internal\n        view\n        returns (IJBTerminal[] memory terminals)\n    {\n        // Use the direct directory view when failures should surface to the caller.\n        if (!shouldIgnoreFailure) return DIRECTORY.terminalsOf(projectId);\n\n        // Fall back to a low-level staticcall so no-code or reverting directories degrade into an empty list.\n        (bool success, bytes memory data) =\n            address(DIRECTORY).staticcall(abi.encodeCall(IJBDirectory.terminalsOf, (projectId)));\n\n        // Return the default empty array when the best-effort lookup failed or returned no payload.\n        if (!success || data.length == 0) return terminals;\n\n        // Decode and return the terminal list when the best-effort lookup succeeded.\n        return abi.decode(data, (IJBTerminal[]));\n    }"
          }
        ],
        "_bestPoolLiquidity": [
          {
            "name": "_bestPoolLiquidity",
            "paramTypes": [
              "address",
              "address"
            ],
            "startLine": 1959,
            "endLine": 1963,
            "source": "function _bestPoolLiquidity(address tokenA, address tokenB) internal view returns (uint128 bestLiquidity) {\n        PoolInfo memory pool = _discoverPool({normalizedTokenIn: tokenA, normalizedTokenOut: tokenB});\n        if (pool.isV4) return _getLiquidity(pool.v4Key.toId());\n        if (address(pool.v3Pool) != address(0)) return pool.v3Pool.liquidity();\n    }"
          }
        ],
